1	package entitlement
2	
3	import (
4		"context"
5		"errors"
6		"time"
7	
8		"github.com/jackc/pgx/v5"
9		"github.com/jackc/pgx/v5/pgconn"
10		"github.com/jackc/pgx/v5/pgxpool"
11	)
12	
13	// PGStore is a PostgreSQL-backed entitlement Service. Every mutating
14	// operation runs in a SERIALIZABLE transaction that takes the entitlement
15	// row lock first, so concurrent allocations and usages against the same
16	// entitlement are serialized and can never oversell it.
17	type PGStore struct {
18		pool *pgxpool.Pool
19		now  func() time.Time
20	}
21	
22	// NewPGStore wraps a connection pool.
23	func NewPGStore(pool *pgxpool.Pool) *PGStore {
24		return &PGStore{pool: pool, now: func() time.Time { return time.Now().UTC() }}
25	}
26	
27	// Migrate creates the required schema. It is safe to call repeatedly.
28	func (s *PGStore) Migrate(ctx context.Context) error {
29		statements := []string{
30			`CREATE TABLE IF NOT EXISTS entitlements (
31				id         TEXT PRIMARY KEY,
32				team_id    TEXT NOT NULL,
33				type       TEXT NOT NULL CHECK (type IN ('seat','quota')),
34				total      INTEGER NOT NULL CHECK (total > 0),
35				status     TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','cancelled')),
36				expires_at TIMESTAMPTZ NOT NULL,
37				used       INTEGER NOT NULL DEFAULT 0 CHECK (used >= 0),
38				version    INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
39				created_at TIMESTAMPTZ NOT NULL DEFAULT now()
40			)`,
41			// A team may only have one grant of the same type with the same
42			// effective deadline; recreating it is a conflict.
43			`CREATE UNIQUE INDEX IF NOT EXISTS entitlements_team_type_expires_key
44				ON entitlements (team_id, type, expires_at)`,
45			`CREATE TABLE IF NOT EXISTS allocations (
46				entitlement_id TEXT NOT NULL REFERENCES entitlements(id) ON DELETE CASCADE,
47				member_id      TEXT NOT NULL,
48				allocated      INTEGER NOT NULL CHECK (allocated > 0),
49				created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
50				PRIMARY KEY (entitlement_id, member_id)
51			)`,
52			`CREATE TABLE IF NOT EXISTS usages (
53				id             BIGSERIAL PRIMARY KEY,
54				entitlement_id TEXT NOT NULL REFERENCES entitlements(id) ON DELETE CASCADE,
55				member_id      TEXT NOT NULL,
56				quantity       INTEGER NOT NULL CHECK (quantity > 0),
57				usage_key      TEXT NOT NULL,
58				result_status  TEXT NOT NULL,
59				result_used    INTEGER NOT NULL,
60				result_version INTEGER NOT NULL,
61				created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
62				UNIQUE (entitlement_id, usage_key)
63			)`,
64			`CREATE INDEX IF NOT EXISTS usages_entitlement_member_idx
65				ON usages (entitlement_id, member_id)`,
66		}
67		for _, stmt := range statements {
68			if _, err := s.pool.Exec(ctx, stmt); err != nil {
69				return err
70			}
71		}
72		return nil
73	}
74	
75	const entitlementColumns = `id, team_id, type, total, status, expires_at, used, version`
76	
77	func scanEntitlement(row pgx.Row) (*Entitlement, error) {
78		var e Entitlement
79		var status string
80		err := row.Scan(&e.ID, &e.TeamID, &e.Type, &e.Total, &status, &e.ExpiresAt, &e.Used, &e.Version)
81		if errors.Is(err, pgx.ErrNoRows) {
82			return nil, errNotFound
83		}
84		if err != nil {
85			return nil, err
86		}
87		e.Status = Status(status)
88		e.ExpiresAt = e.ExpiresAt.UTC()
89		return &e, nil
90	}
91	
92	// present applies read-time rules (expiry) to a stored row.
93	func (s *PGStore) present(e *Entitlement) *Entitlement {
94		c := *e
95		c.Status = effectiveStatus(e.Status, e.ExpiresAt, s.now())
96		return &c
97	}
98	
99	func isPGCode(err error, code string) bool {
100		var pgErr *pgconn.PgError
101		return errors.As(err, &pgErr) && pgErr.Code == code
102	}
103	
104	func isSerializationFailure(err error) bool { return isPGCode(err, "40001") }
105	
106	// transact runs fn in a serializable transaction, retrying serialization
107	// failures. Any non-nil error from fn rolls the transaction back, which is
108	// what makes failed requests leave no trace.
109	func (s *PGStore) transact(ctx context.Context, fn func(pgx.Tx) error) error {
110		const maxAttempts = 3
111		var err error
112		for attempt := 0; attempt < maxAttempts; attempt++ {
113			tx, beginErr := s.pool.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.Serializable})
114			if beginErr != nil {
115				return beginErr
116			}
117			err = fn(tx)
118			if err == nil {
119				if commitErr := tx.Commit(ctx); commitErr != nil {
120					err = commitErr
121				}
122			}
123			if err != nil {
124				_ = tx.Rollback(ctx)
125			}
126			if !isSerializationFailure(err) {
127				return err
128			}
129		}
130		return err
131	}
132	
133	func (s *PGStore) existingForConflict(ctx context.Context, tx pgx.Tx, params CreateParams) (*Entitlement, error) {
134		row := tx.QueryRow(ctx,
135			`SELECT `+entitlementColumns+` FROM entitlements
136			 WHERE team_id=$1 AND type=$2 AND expires_at=$3`,
137			params.TeamID, params.Type, params.ExpiresAt)
138		e, err := scanEntitlement(row)
139		if err != nil {
140			return nil, err
141		}
142		return s.present(e), nil
143	}
144	
145	// Create inserts a new active entitlement. A duplicate (same team, type and
146	// expiry) is rejected with 409 and the record that already exists.
147	func (s *PGStore) Create(ctx context.Context, params CreateParams) (*Entitlement, error) {
148		if err := validateCreate(params); err != nil {
149			return nil, err
150		}
151		params.ExpiresAt = params.ExpiresAt.UTC()
152	
153		var created *Entitlement
154		err := s.transact(ctx, func(tx pgx.Tx) error {
155			row := tx.QueryRow(ctx,
156				`INSERT INTO entitlements (id, team_id, type, total, status, expires_at, used, version)
157				 VALUES (gen_random_uuid()::text, $1, $2, $3, 'active', $4, 0, 1)
158				 RETURNING `+entitlementColumns,
159				params.TeamID, params.Type, params.Total, params.ExpiresAt)
160			e, err := scanEntitlement(row)
161			if err != nil {
162				if isPGCode(err, "23505") {
163					existing, lookupErr := s.existingForConflict(ctx, tx, params)
164					if lookupErr != nil {
165						return lookupErr
166					}
167					return &ConflictError{
168						APIError: APIError{Kind: KindConflict, Code: "entitlement_already_exists",
169							Message: "an active entitlement with the same team, type and expiry already exists"},
170						Existing: existing,
171					}
172				}
173				return err
174			}
175			created = e
176			return nil
177		})
178		if err != nil {
179			return nil, err
180		}
181		return s.present(created), nil
182	}
183	
184	// Get returns an entitlement or a not-found error. Expiry is derived.
185	func (s *PGStore) Get(ctx context.Context, id string) (*Entitlement, error) {
186		if err := validateTarget(id); err != nil {
187			return nil, err
188		}
189		row := s.pool.QueryRow(ctx,
190			`SELECT `+entitlementColumns+` FROM entitlements WHERE id=$1`, id)
191		e, err := scanEntitlement(row)
192		if err != nil {
193			return nil, err
194		}
195		return s.present(e), nil
196	}
197	
198	// lockEntitlement fetches an entitlement row FOR UPDATE and verifies it can
199	// still be operated on.
200	func (s *PGStore) lockEntitlement(ctx context.Context, tx pgx.Tx, id string) (*Entitlement, error) {
201		row := tx.QueryRow(ctx,
202			`SELECT `+entitlementColumns+` FROM entitlements WHERE id=$1 FOR UPDATE`, id)
203		e, err := scanEntitlement(row)
204		if err != nil {
205			return nil, err
206		}
207		switch effectiveStatus(e.Status, e.ExpiresAt, s.now()) {
208		case Cancelled:
209			return nil, conflict("entitlement_cancelled", "entitlement %s has been cancelled and can no longer be changed", id)
210		case Expired:
211			return nil, conflict("entitlement_expired", "entitlement %s expired at %s and can no longer be changed", id, e.ExpiresAt.Format(time.RFC3339))
212		}
213		return e, nil
214	}
215	
216	// Allocate grants quantity seats/quota to a member, subject to total.
217	func (s *PGStore) Allocate(ctx context.Context, id, memberID string, quantity int) (*Entitlement, error) {
218		if err := validateTarget(id); err != nil {
219			return nil, err
220		}
221		if err := validateAllocate(memberID, quantity); err != nil {
222			return nil, err
223		}
224	
225		var updated *Entitlement
226		err := s.transact(ctx, func(tx pgx.Tx) error {
227			e, err := s.lockEntitlement(ctx, tx, id)
228			if err != nil {
229				return err
230			}
231			if e.Used+quantity > e.Total {
232				return conflict("allocation_exceeds_total",
233					"cannot allocate %d: %d of %d already allocated", quantity, e.Used, e.Total)
234			}
235			if _, err := tx.Exec(ctx,
236				`INSERT INTO allocations (entitlement_id, member_id, allocated)
237				 VALUES ($1, $2, $3)
238				 ON CONFLICT (entitlement_id, member_id)
239				 DO UPDATE SET allocated = allocations.allocated + EXCLUDED.allocated`,
240				id, memberID, quantity); err != nil {
241				return err
242			}
243			row := tx.QueryRow(ctx,
244				`UPDATE entitlements SET used = used + $2, version = version + 1
245				 WHERE id = $1 RETURNING `+entitlementColumns,
246				id, quantity)
247			updated, err = scanEntitlement(row)
248			return err
249		})
250		if err != nil {
251			return nil, err
252		}
253		return s.present(updated), nil
254	}
255	
256	// Use consumes quantity for a member. A repeated usageKey replays the first
257	// result instead of accumulating again; a reused key with different request
258	// parameters is rejected.
259	func (s *PGStore) Use(ctx context.Context, id, memberID string, quantity int, usageKey string) (*Entitlement, UsageRecord, bool, error) {
260		if err := validateTarget(id); err != nil {
261			return nil, UsageRecord{}, false, err
262		}
263		if err := validateUse(memberID, quantity, usageKey); err != nil {
264			return nil, UsageRecord{}, false, err
265		}
266	
267		var (
268			updated  *Entitlement
269			record   UsageRecord
270			replayed bool
271		)
272		err := s.transact(ctx, func(tx pgx.Tx) error {
273			e, err := s.lockEntitlement(ctx, tx, id)
274			if err != nil {
275				return err
276			}
277	
278			// Idempotency: a prior successful usage with this key wins. The key
279			// is unique per entitlement. Snapshots make the replay byte-for-byte
280			// identical to the first response even after later operations.
281			var existingMember, replayStatus string
282			var existingQty, replayUsed, replayVersion int
283			lookupErr := tx.QueryRow(ctx,
284				`SELECT member_id, quantity, result_status, result_used, result_version
285				 FROM usages WHERE entitlement_id=$1 AND usage_key=$2`,
286				id, usageKey).Scan(&existingMember, &existingQty, &replayStatus, &replayUsed, &replayVersion)
287			switch {
288			case lookupErr == nil:
289				if existingMember != memberID || existingQty != quantity {
290					return &UsageKeyConflictError{
291						APIError: APIError{Kind: KindConflict, Code: "usage_key_reused",
292							Message: "usageKey was already used with different memberId or quantity"},
293						Existing: UsageRecord{MemberID: existingMember, Quantity: existingQty, UsageKey: usageKey},
294					}
295				}
296				record = UsageRecord{MemberID: existingMember, Quantity: existingQty, UsageKey: usageKey}
297				replayed = true
298				replay := *e
299				replay.Status = Status(replayStatus)
300				replay.Used = replayUsed
301				replay.Version = replayVersion
302				updated = &replay
303				return nil
304			case !errors.Is(lookupErr, pgx.ErrNoRows):
305				return lookupErr
306			}
307	
308			// Member's unused headroom = allocated - already consumed.
309			var allocated, consumed int
310			if err := tx.QueryRow(ctx,
311				`SELECT COALESCE((SELECT allocated FROM allocations
312				                 WHERE entitlement_id=$1 AND member_id=$2), 0),
313				        COALESCE((SELECT SUM(quantity) FROM usages
314				                 WHERE entitlement_id=$1 AND member_id=$2), 0)`,
315				id, memberID).Scan(&allocated, &consumed); err != nil {
316				return err
317			}
318			remaining := allocated - consumed
319			if remaining < quantity {
320				return conflict("usage_exceeds_member_remaining",
321					"member %s has %d unused but requested %d", memberID, remaining, quantity)
322			}
323	
324			// Bump the entitlement first; if the usage insert below fails the
325			// whole transaction rolls back, so failed requests leave no trace.
326			row := tx.QueryRow(ctx,
327				`UPDATE entitlements SET used = used + $2, version = version + 1
328				 WHERE id = $1 RETURNING used, version`,
329				id, quantity)
330			var newUsed, newVersion int
331			if err := row.Scan(&newUsed, &newVersion); err != nil {
332				return err
333			}
334			if _, err := tx.Exec(ctx,
335				`INSERT INTO usages (entitlement_id, member_id, quantity, usage_key,
336				                     result_status, result_used, result_version)
337				 VALUES ($1, $2, $3, $4, 'active', $5, $6)`,
338				id, memberID, quantity, usageKey, newUsed, newVersion); err != nil {
339				if isPGCode(err, "23505") {
340					// Concurrent insert won the key; rollback undoes the bump.
341					return conflict("usage_key_reused", "usageKey %q is already in use for this entitlement", usageKey)
342				}
343				return err
344			}
345			updated = &Entitlement{
346				ID:        e.ID,
347				TeamID:    e.TeamID,
348				Type:      e.Type,
349				Total:     e.Total,
350				Status:    Active,
351				ExpiresAt: e.ExpiresAt,
352				Used:      newUsed,
353				Version:   newVersion,
354			}
355			record = UsageRecord{MemberID: memberID, Quantity: quantity, UsageKey: usageKey}
356			return nil
357		})
358		if err != nil {
359			return nil, UsageRecord{}, false, err
360		}
361		return s.present(updated), record, replayed, nil
362	}
363	
364	// Cancel revokes an entitlement. Already-used quantities are preserved;
365	// cancelling an already-cancelled grant replays success, while expired
366	// grants cannot be cancelled.
367	func (s *PGStore) Cancel(ctx context.Context, id string) (*Entitlement, error) {
368		if err := validateTarget(id); err != nil {
369			return nil, err
370		}
371	
372		var updated *Entitlement
373		err := s.transact(ctx, func(tx pgx.Tx) error {
374			e, err := s.lockEntitlement(ctx, tx, id)
375			if err != nil {
376				return err
377			}
378			row := tx.QueryRow(ctx,
379				`UPDATE entitlements SET status='cancelled', version = version + 1
380				 WHERE id = $1 RETURNING `+entitlementColumns, id)
381			updated, err = scanEntitlement(row)
382			_ = e
383			return err
384		})
385		if err != nil {
386			return nil, err
387		}
388		return s.present(updated), nil
389	}
390	
391	// Detail returns an entitlement and its per-member consumption breakdown.
392	func (s *PGStore) Detail(ctx context.Context, id string) (*Detail, error) {
393		if err := validateTarget(id); err != nil {
394			return nil, err
395		}
396	
397		detail := &Detail{}
398		err := s.transact(ctx, func(tx pgx.Tx) error {
399			row := tx.QueryRow(ctx,
400				`SELECT `+entitlementColumns+` FROM entitlements WHERE id=$1 FOR SHARE`, id)
401			e, err := scanEntitlement(row)
402			if err != nil {
403				return err
404			}
405			detail.Entitlement = *s.present(e)
406	
407			rows, err := tx.Query(ctx,
408				`SELECT a.member_id,
409				        COALESCE(SUM(u.quantity), 0) AS used,
410				        COALESCE(array_agg(u.usage_key ORDER BY u.id) FILTER (WHERE u.usage_key IS NOT NULL), ARRAY[]::text[])
411				 FROM allocations a
412				 LEFT JOIN usages u
413				   ON u.entitlement_id = a.entitlement_id AND u.member_id = a.member_id
414				 WHERE a.entitlement_id = $1
415				 GROUP BY a.member_id
416				 ORDER BY a.member_id`, id)
417			if err != nil {
418				return err
419			}
420			defer rows.Close()
421	
422			detail.Members = []MemberUsage{}
423			for rows.Next() {
424				var mu MemberUsage
425				if err := rows.Scan(&mu.MemberID, &mu.Used, &mu.UsageKeys); err != nil {
426					return err
427				}
428				if mu.UsageKeys == nil {
429					mu.UsageKeys = []string{}
430				}
431				detail.Members = append(detail.Members, mu)
432			}
433			return rows.Err()
434		})
435		if err != nil {
436			return nil, err
437		}
438		return detail, nil
439	}
440	
441	// ConflictError carries the pre-existing entitlement back on create conflicts.
442	type ConflictError struct {
443		APIError
444		Existing *Entitlement
445	}
446	
447	// UsageKeyConflictError carries the first usage recorded for a reused key.
