	if conflict.Existing.ID != e.ID {
		t.Fatalf("conflict returned %s, want existing %s", conflict.Existing.ID, e.ID)
	}
	if conflict.Kind != KindConflict {
		t.Fatalf("kind=%v", conflict.Kind)
	}
}

func asConflict(err error, target **ConflictError) bool {
	var c *ConflictError
	if apiErr, ok := AsAPIError(err); ok && apiErr.Code == "entitlement_already_exists" {
		if e, ok := err.(*ConflictError); ok {
			c = e
		}
	}
	if c != nil {
		*target = c
		return true
	}
	return false
}

