func isSerializationFailure(err error) bool { return isPGCode(err, "40001") }

// transact runs fn in a serializable transaction, retrying serialization
// failures. Any non-nil error from fn rolls the transaction back, which is
// what makes failed requests leave no trace.
func (s *PGStore) transact(ctx context.Context, fn func(pgx.Tx) error) error {
	const maxAttempts = 3
	var err error
	for attempt := 0; attempt < maxAttempts; attempt++ {
		tx, beginErr := s.pool.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.Serializable})
		if beginErr != nil {
			return beginErr
		}
		err = fn(tx)
		if err == nil {
			if commitErr := tx.Commit(ctx); commitErr != nil {
				err = commitErr
			}
		}
		if err != nil {
			_ = tx.Rollback(ctx)
		}
		if !isSerializationFailure(err) {
			return err
		}
	}
	return err
}

